"""Strict complete AI source scope; all previous validation bodies remain exact."""
from pathlib import Path
import json,hashlib,subprocess
BASE='4337b2f4ede0a24a54a925eb8a789eb37f8362a4'
MANIFEST='docs/evidence/cp6-ai-gate-pins.json'
PATCHES={'.github/workflows/cp6-full-schema-validation.yml': [['          # BEGIN AH INDEPENDENT ROUTE\n', "          # BEGIN AI QUALIFIED ROUTE\n          ai_review=False\n          if Path('scripts/cp6_ai_gate_scope.py').exists():\n              ai_review=subprocess.run(['python','scripts/cp6_ai_gate_scope.py'],capture_output=True).returncode==0\n          # END AI QUALIFIED ROUTE\n          # BEGIN AH INDEPENDENT ROUTE\n"], ['              reuse=audit_only or ad_exact or ad_round or ae_exact or ae_independent or af_exact or af_review or ag_review or ag_residual or ah_review or ah_independent\n', '              reuse=audit_only or ad_exact or ad_round or ae_exact or ae_independent or af_exact or af_review or ag_review or ag_residual or ah_review or ah_independent or ai_review\n']], '.github/workflows/cp6-ad-roll-opening-check.yml': [[' || python scripts/cp6_ah_review_scope.py; then\n', ' || python scripts/cp6_ah_review_scope.py || python scripts/cp6_ai_gate_scope.py; then\n']], '.github/workflows/cp6-ac-independent-audit.yml': [['          # BEGIN AH INDEPENDENT ROUTE\n', "          # BEGIN AI QUALIFIED ROUTE\n          if Path('scripts/cp6_ai_gate_scope.py').exists():\n              from cp6_ai_gate_scope import verify\n              verify()\n              with open(os.environ['GITHUB_OUTPUT'], 'a') as output:\n                  output.write('ae=true\\n')\n              raise SystemExit(0)\n          # END AI QUALIFIED ROUTE\n          # BEGIN AH INDEPENDENT ROUTE\n"]], '.github/workflows/cp6-ag-sale-reservation.yml': [[' || python scripts/cp6_ah_review_scope.py; then\n', ' || python scripts/cp6_ah_review_scope.py || python scripts/cp6_ai_gate_scope.py; then\n']], '.github/workflows/cp6-ah-return-allocation.yml': [['jobs:\n  review:\n', 'jobs:\n  # BEGIN AI QUALIFIED ROUTE\n  review-scope:\n    runs-on: ubuntu-24.04\n    outputs:\n      ai: ${{ steps.scope.outputs.ai }}\n    steps:\n    - uses: actions/checkout@v4\n      with:\n        fetch-depth: 0\n    - id: scope\n      shell: bash\n      run: |\n        set -euo pipefail\n        if python scripts/cp6_ai_gate_scope.py; then\n          echo \'ai=true\' >> "$GITHUB_OUTPUT"\n        else\n          echo \'ai=false\' >> "$GITHUB_OUTPUT"\n        fi\n  # END AI QUALIFIED ROUTE\n  review:\n    needs: review-scope\n    if: needs.review-scope.outputs.ai != \'true\'\n']], '.github/workflows/cp6-ah-independent-review.yml': [['jobs:\n  review:\n', 'jobs:\n  # BEGIN AI QUALIFIED ROUTE\n  review-scope:\n    runs-on: ubuntu-24.04\n    outputs:\n      ai: ${{ steps.scope.outputs.ai }}\n    steps:\n    - uses: actions/checkout@v4\n      with:\n        fetch-depth: 0\n    - id: scope\n      shell: bash\n      run: |\n        set -euo pipefail\n        if python scripts/cp6_ai_gate_scope.py; then\n          echo \'ai=true\' >> "$GITHUB_OUTPUT"\n        else\n          echo \'ai=false\' >> "$GITHUB_OUTPUT"\n        fi\n  # END AI QUALIFIED ROUTE\n  review:\n    needs: review-scope\n    if: needs.review-scope.outputs.ai != \'true\'\n']]}
EXPECTED={'.github/workflows/cp6-ag-sale-reservation.yml', 'scripts/cp6_v2620ai_family.py', '.github/workflows/cp6-ah-return-allocation.yml', 'supabase/rollbacks/20260916090022_erp_v2_6_20ai_cp6_work_source_lineage.rollback.sql', 'scripts/cp6_v2620ai_runtime.py', 'docs/evidence/cp6-ai-predecessor-functions.json', 'scripts/cp6_preuse_rollback_maintenance.py', 'scripts/check-cp6-expanded-audit-closure.mjs', 'scripts/check-cp6-h2-audit-closure.mjs', '.github/workflows/cp6-ac-independent-audit.yml', '.github/workflows/cp6-ai-work-source.yml', 'scripts/cp6_v2620ai_build_sql.py', 'scripts/cp6_ai_gate_scope.py', 'supabase/migrations/20260916090022_erp_v2_6_20ai_cp6_work_source_lineage.sql', '.github/workflows/cp6-ad-roll-opening-check.yml', 'docs/evidence/cp6-ai-family-disposition.json', 'scripts/cp6_v2620ai_concurrency.py', '.github/workflows/cp6-full-schema-validation.yml', 'scripts/cp6_ah_independent_review.py', '.github/workflows/cp6-ah-independent-review.yml', 'docs/cp6-ai-competition-handoff.md', 'scripts/cp6_v2620ai_maintenance_schedules.py', 'docs/evidence/cp6-ai-runtime-pins.json', 'scripts/cp6_v2620ai_rollback_guards.py', 'docs/evidence/cp6-ai-ah-catalog-pins.json'}
def verify():
 git=lambda *a:subprocess.check_output(['git',*a],text=True).strip()
 assert git('merge-base',BASE,'HEAD')==BASE and not git('rev-list','--merges',BASE+'..HEAD')
 p=json.loads(Path(MANIFEST).read_text());assert p['base']==BASE and p['production_go'] is False
 assert set(p['source_pins'])==EXPECTED
 assert set(git('diff','--name-only',BASE,'HEAD').splitlines())==EXPECTED|{MANIFEST}
 for path,pin in p['source_pins'].items():
  b=Path(path).read_bytes();assert len(b)==pin['bytes'] and hashlib.sha256(b).hexdigest()==pin['sha256'],'AI_GATE_SOURCE_DRIFT:'+path
 for path,edits in PATCHES.items():
  s=Path(path).read_text()
  for old,new in reversed(edits):
   assert s.count(new)==1,(path,'route missing or repeated')
   s=s.replace(new,old,1)
  assert s==subprocess.check_output(['git','show',BASE+':'+path],text=True),'ORIGINAL_VALIDATION_BODY_CHANGED:'+path
 return dict(status='ROUTED_TO_AI_QUALIFIED_NATIVE_GATE',head=git('rev-parse','HEAD'),tree=git('rev-parse','HEAD^{tree}'),historical_500_matrix_reexecuted=False,ai_native_result_required=True,independent_ai_acceptance=False,production_go=False)
if __name__=='__main__':print(json.dumps(verify()))
